<?php require_once __DIR__.'/inc/common.php';require_employee();$rows=db()->query('SELECT h.id,h.contract_code,h.start_date,h.end_date,h.total_amount,c.full_name,v.license_plate FROM contracts h JOIN customers c ON c.id=h.customer_id JOIN cars v ON v.id=h.car_id ORDER BY h.id DESC')->fetchAll();page_start('Danh sách hợp đồng');?><div class="heading"><div><span class="eyebrow">UC27 / HỢP ĐỒNG</span><h1>Hợp đồng đã lập</h1></div></div><div class="card tablewrap"><table><thead><tr><th>Số hợp đồng</th><th>Khách hàng</th><th>Biển số</th><th>Thời gian</th><th>Tổng phí</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=esc($r['contract_code'])?></b></td><td><?=esc($r['full_name'])?></td><td><?=esc($r['license_plate'])?></td><td><?=esc($r['start_date'].' → '.$r['end_date'])?></td><td><?=money($r['total_amount'])?></td><td><a class="textlink" href="contract_view.php?id=<?=intval($r['id'])?>">Chi tiết →</a></td></tr><?php endforeach;?></tbody></table></div><?php page_end(); ?>
